REVOKE INSERT,UPDATE,DELETE ON public.campaign_letters,public.letter_replies FROM anon,authenticated;
REVOKE SELECT ON public.house_catalog FROM anon,authenticated;
GRANT SELECT(id,name,region,classification,archive_data,public_reviewed,updated_at,gallery,narrative_text) ON public.house_catalog TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.open_letter_round() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT number FROM public.letter_rounds WHERE status='open' $$;
CREATE OR REPLACE FUNCTION public.schedule_letter_draft(p_id uuid,p_week integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer:=public.open_letter_round();target integer; BEGIN IF NOT public.campaign_access_active() THEN RAISE EXCEPTION 'Jogador não autorizado'; END IF; IF NOT public.is_campaign_admin() AND n IS NULL THEN RAISE EXCEPTION 'Missivas fechadas, aguarde o narrador abrir a próxima semana'; END IF; target:=CASE WHEN public.is_campaign_admin() THEN p_week ELSE n END; IF target IS NULL OR target<1 OR EXISTS(SELECT 1 FROM public.letter_rounds WHERE number=target AND status='closed') THEN RAISE EXCEPTION 'Semana de entrega inválida'; END IF; UPDATE public.campaign_letters SET delivery_week=target,letter_number=target,creation_week=coalesce(n,target),publication_state=CASE WHEN target=n THEN 'delivered' ELSE 'scheduled' END,delivered_at=CASE WHEN target=n THEN now() END WHERE id=p_id AND sender_user_id=auth.uid() AND publication_state='draft' AND btrim(subject)<>'' AND btrim(content)<>''; IF NOT FOUND THEN RAISE EXCEPTION 'Preencha o rascunho antes de enviar'; END IF; INSERT INTO public.sync_outbox(entity_type,entity_id,version,payload) SELECT 'letter',l.id,l.version,to_jsonb(l) FROM public.campaign_letters l WHERE l.id=p_id ON CONFLICT DO NOTHING; UPDATE public.sync_outbox SET state='pending',next_attempt_at=now() WHERE entity_id=p_id; END $$;
CREATE OR REPLACE FUNCTION public.delete_campaign_letter(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.campaign_letters; BEGIN IF NOT public.campaign_access_active() THEN RAISE EXCEPTION 'Jogador não autorizado'; END IF; SELECT * INTO l FROM public.campaign_letters WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Missiva não encontrada'; END IF; IF NOT (public.is_campaign_admin() OR l.sender_user_id=auth.uid()) THEN RAISE EXCEPTION 'Só quem enviou pode excluir esta missiva'; END IF; UPDATE public.campaign_letters SET deleted_at=now(),deleted_by=auth.uid() WHERE id=p_id; END $$;